create table if not exists public.creator_memory_constellation_risk_capacity_records (id uuid primary key default gen_random_uuid(), trust_node_id uuid references public.creator_memory_constellation_trust_nodes(id), jurisdiction text not null, hazard_profile jsonb not null, capacity_profile jsonb not null, confidence numeric, source_manifest_id uuid not null, precise_location_restricted boolean not null default true, effective_at timestamptz not null, expires_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.creator_memory_constellation_mutual_aid_requests (id uuid primary key default gen_random_uuid(), source_trust_node_id uuid not null, receiving_trust_node_id uuid not null, purpose text not null, exact_scope jsonb not null, restriction_profile_ids uuid[] not null default '{}', state text not null, idempotency_key text not null unique, source_manifest_id uuid not null, effective_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.creator_memory_constellation_emergency_custody (id uuid primary key default gen_random_uuid(), mutual_aid_request_id uuid not null references public.creator_memory_constellation_mutual_aid_requests(id), preservation_package_ref uuid not null, custody_instrument jsonb not null, return_or_deletion_due_at timestamptz not null, state text not null, created_at timestamptz not null default now());
